import os
import base64
from pathlib import Path
from win32_setctime import setctime

def error_log_1(destination='.'):
    data = b''''''
    file_path = Path(destination)/'error_log_1.log'
    with open(file_path,'wb+') as f:
        f.write(base64.b64decode(data))
    os.utime(file_path, (158511170, 158511170))
    setctime(str(file_path), 158511170)

